import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.B9qR_F1m.js";const i="/assets/c67ce7e689ad8a83.CCP7kIrh.svg",n="/assets/a203fa6c87084781.CFvgo3Py.svg",s="/assets/537d2ed4f52a073f.CadJkyWN.svg",f=JSON.parse(`{"title":"Architecture Overview","description":"How the Feluqa SDK, CLI, artifacts, Platform, Applications, and clients fit together, and what is generated at compile time.","frontmatter":{"sidebarTitle":"Architecture","icon":"network","title":"Architecture Overview","description":"How the Feluqa SDK, CLI, artifacts, Platform, Applications, and clients fit together, and what is generated at compile time.","summary":"Presents Feluqa's target architecture, from Product and Module composition through SDK, CLI, generated artifacts, runtime layers, target profiles, and client interaction surfaces. It describes compile-time generation, execution and deployment flows, desktop console options, platform capabilities, and design targets, while identifying what the current implementation does not yet deliver.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":4,"status":"Target","tags":["feluqa","architecture","overview","mermaid","sdk"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"get-started/introduction/architecture-overview.md","filePath":"get-started/introduction/architecture-overview.md"}`),d={name:"get-started/introduction/architecture-overview.md"};function l(c,e,p,h,u,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Products compose applications; applications compose modules.</strong> A product is the solution people use. An application is a deployable program for one target role. Modules provide reusable business capabilities inside it.</li><li><strong>Write only business logic.</strong> Routes, permissions, sidebar, SDUI schemas, manifests and configuration files are generated at compile time.</li><li><strong>No manual registry, no magic strings.</strong> Everything is declared with attributes (<code>#[panel]</code>, <code>#[resource]</code>, <code>#[permissions]</code>, <code>#[gate]</code>, ...) and collected by the compile-time scanner.</li><li><strong>Context is implicit.</strong> The scanner knows the current module, so you write <code>Refund</code>, not <code>sales.refund</code>. The full path is still accepted.</li><li><strong>Secure by default.</strong> A write handler without <code>#[gate]</code> does not compile.</li><li><strong>One file, one responsibility.</strong> One resource per file. No catch-all <code>mod.rs</code> or <code>admin.rs</code>.</li><li><strong>One entry point.</strong> The Feluqa developer kit (SDK) provides a consistent Rust interface for application capabilities such as user interfaces, panels, authentication, and resources.</li><li><strong>Server is the source of truth.</strong> Hiding something in the client is never protection.</li></ol><h2 id="the-pieces-and-where-they-run" tabindex="-1">The pieces and where they run <a class="header-anchor" href="#the-pieces-and-where-they-run" aria-label="Permalink to &quot;The pieces and where they run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th><th>When it matters</th><th>Where it runs</th></tr></thead><tbody><tr><td><strong>Feluqa SDK</strong></td><td>The library you build with: attributes, the compile-time scanner, the single <code>feluqa</code> namespace.</td><td>While you write and compile</td><td>Developer machine, linked into the Application</td></tr><tr><td><strong>Feluqa CLI</strong></td><td>Creates, validates, builds, installs and operates projects.</td><td>Development and operations</td><td>Developer machine and servers</td></tr><tr><td><strong>Feluqa Platform</strong></td><td>Authentication, access control, audit, configuration, System panel.</td><td>Runtime</td><td>Server</td></tr><tr><td><strong>Application</strong></td><td>A target-specific program composed of one or more modules.</td><td>Runtime</td><td>Server, workstation, mobile, or another target</td></tr></tbody></table><p>Most people work with these four parts through the application and its tools.</p><h2 id="from-modules-to-application-artifacts" tabindex="-1">From modules to application artifacts <a class="header-anchor" href="#from-modules-to-application-artifacts" aria-label="Permalink to &quot;From modules to application artifacts&quot;">​</a></h2><p>A Product can provide several Applications for different target roles. Each Application composes the modules it needs; each target build produces an artifact for that Application and target profile.</p><p><img src="'+i+'" alt="Mermaid diagram"></p><h2 id="end-to-end-flow" tabindex="-1">End-to-end flow <a class="header-anchor" href="#end-to-end-flow" aria-label="Permalink to &quot;End-to-end flow&quot;">​</a></h2><p>What happens between writing code and a running system:</p><p><img src="'+n+'" alt="Mermaid diagram"></p><h2 id="runtime-layers" tabindex="-1">Runtime layers <a class="header-anchor" href="#runtime-layers" aria-label="Permalink to &quot;Runtime layers&quot;">​</a></h2><p><img src="'+s+'" alt="Mermaid diagram"> The SDUI schema sent to the client is <strong>already filtered server-side</strong>: an entry the user may not see is never serialized.</p><h2 id="what-is-generated-and-never-edited" tabindex="-1">What is generated and never edited <a class="header-anchor" href="#what-is-generated-and-never-edited" aria-label="Permalink to &quot;What is generated and never edited&quot;">​</a></h2><p>Generated into <code>target/feluqa/</code>, never edited and never committed:</p><ul><li>module manifests and the route table;</li><li>the permission table (consumed by the System panel);</li><li>configuration schemas and <code>.env.example</code>;</li><li>reference documentation.</li></ul><p><code>feluqa.toml</code> (application) and <code>module.toml</code> (module) are build contexts. The current CLI creates the application manifest with <code>feluqa new</code>; module generation remains a separate capability.</p><h2 id="target-profiles" tabindex="-1">Target profiles <a class="header-anchor" href="#target-profiles" aria-label="Permalink to &quot;Target profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profile</th><th>Typical use</th><th>Storage</th><th>Status</th></tr></thead><tbody><tr><td><code>server</code></td><td>Hosted backend, multi-user web app</td><td>PostgreSQL, or SQLite for small single-server installs</td><td>Partial</td></tr><tr><td><code>workstation</code></td><td>Standalone local app on a desktop</td><td>SQLite in the user data directory</td><td>Target</td></tr><tr><td><code>embedded</code> (<code>no_std</code>)</td><td>Telemetry, sensor ingestion</td><td>Minimal or none</td><td>Exploring</td></tr></tbody></table><p>Shared Modules are intended to work across separate Applications built for different target profiles. Server and workstation composition, connectivity, synchronization, and offline behavior remain product goals whose design is still being worked out.</p><h2 id="interaction-surfaces-and-desktop-hosts" tabindex="-1">Interaction surfaces and desktop hosts <a class="header-anchor" href="#interaction-surfaces-and-desktop-hosts" aria-label="Permalink to &quot;Interaction surfaces and desktop hosts&quot;">​</a></h2><p>An application&#39;s target profile and its interaction surface are separate choices. <code>workstation</code> describes where and how the application runtime is deployed; <code>console</code>, <code>graphical</code>, or <code>mixed</code> describes how a person interacts with it. A console application is therefore not limited to a shell window on the developer&#39;s operating system.</p><p>Feluqa may provide a workstation host that presents a console application in a terminal-style desktop window. A separate product experience could combine a graphical desktop interface with an integrated terminal for console commands. These experiences need a desktop host that connects the window to the Feluqa console runtime; a Rust binary or a <code>workstation</code> profile alone does not provide that host. Neither desktop terminal experience is currently implemented. Host-shell selection and its build configuration remain product and architecture work.</p><h2 id="platform-capabilities" tabindex="-1">Platform capabilities <a class="header-anchor" href="#platform-capabilities" aria-label="Permalink to &quot;Platform capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Feluqa CLI</strong></td><td>Creates, validates, builds, installs, and operates projects, modules, and applications.</td></tr><tr><td><strong>Modules</strong></td><td>Self-contained units of business functionality with their own version, permissions, and features.</td></tr><tr><td><strong>Target profiles</strong></td><td>Select dependencies and capabilities for server, workstation, and constrained <code>no_std</code> builds.</td></tr><tr><td><strong>Feluqa SDK</strong></td><td>Provides attributes, panels, resources, and the compile-time scanner through a single <code>feluqa</code> entry point.</td></tr><tr><td><strong>Feluqa Platform</strong></td><td>The planned server-side runtime and control plane, including a System panel for authentication, schema management, and access control.</td></tr><tr><td><strong>Authorization</strong></td><td>Defines privileges, roles, permissions, and policies. Runtime authorization remains necessary even when compile-time checks are available.</td></tr><tr><td><strong>Storage</strong></td><td>Uses embedded SQLite as the proposed local default, with other strategies depending on deployment needs.</td></tr></tbody></table><h2 id="design-targets" tabindex="-1">Design targets <a class="header-anchor" href="#design-targets" aria-label="Permalink to &quot;Design targets&quot;">​</a></h2><p>These figures and capabilities are <strong>design targets</strong>, not measured guarantees; they have not yet been revalidated.</p><table tabindex="0"><thead><tr><th>Area</th><th>Target</th><th>Why it matters</th></tr></thead><tbody><tr><td>Language</td><td>Native Rust</td><td>Memory safety and control over runtime costs.</td></tr><tr><td>Hot-path latency</td><td>Sub-millisecond p50</td><td>A target for selected operations, not an end-to-end or real-time guarantee.</td></tr><tr><td>Local persistence</td><td>SQLite by default</td><td>Reduces setup requirements for standalone deployments.</td></tr><tr><td>Security boundaries</td><td>Separate platform, application, and user scopes</td><td>Makes ownership and access rules explicit.</td></tr><tr><td>Access control</td><td>Privileges, roles, permissions, and policies</td><td>Combines compile-time validation where possible with runtime authorization.</td></tr></tbody></table>',29)])])}const b=t(d,[["render",l]]);export{f as __pageData,b as default};
